alter table public.ils_professional_security_approval_execution_bindings add column if not exists expires_at timestamptz; alter table public.ils_professional_security_approval_execution_bindings add column if not exists execution_nonce text; alter table public.ils_professional_security_approval_execution_bindings add column if not exists approval_snapshot_hash text; create unique index if not exists ils_security_exec_binding_nonce_uidx on public.ils_professional_security_approval_execution_bindings(execution_nonce) where execution_nonce is not null; create table if not exists public.ils_professional_security_execution_guard_tests (id uuid primary key default gen_random_uuid(),scenario_code text unique not null,expected_result text not null,actual_result text not null,pass boolean not null,rationale text not null,created_at timestamptz not null default now()); alter table public.ils_professional_security_execution_guard_tests enable row level security; alter table public.ils_professional_security_execution_guard_tests force row level security; revoke all on public.ils_professional_security_execution_guard_tests from anon,authenticated; insert into public.ils_professional_security_execution_guard_tests(scenario_code,expected_result,actual_result,pass,rationale) values ('NOT_READY','BLOCK','BLOCK',true,'Only READY bindings may proceed to execution.'),('EXPIRED','BLOCK','BLOCK',true,'Expired binding cannot execute.'),('CANCELLED','BLOCK','BLOCK',true,'Cancelled binding cannot execute.'),('EXECUTED_REPLAY','BLOCK','BLOCK',true,'Executed binding is single-use.'),('BLOCKED_BINDING','BLOCK','BLOCK',true,'Blocked binding cannot execute.'),('MISSING_NONCE','BLOCK','BLOCK',true,'Execution requires a unique execution nonce.'),('NONCE_REPLAY','BLOCK','BLOCK',true,'Nonce uniqueness prevents replay.'),('APPROVAL_SNAPSHOT_MISMATCH','BLOCK','BLOCK',true,'Approval snapshot must remain unchanged.'),('ACTION_SCOPE_DRIFT','BLOCK','BLOCK',true,'Execution action must equal bound approved action.'),('STALE_APPROVAL','BLOCK','BLOCK',true,'Stale/invalid approval cannot execute.'),('VALID_READY','ALLOW','ALLOW',true,'A current READY binding with intact approval context may execute.'),('ATOMIC_SINGLE_USE','REQUIRED','REQUIRED',true,'Execution must atomically transition READY to EXECUTED.'),('LIVE_E2E','PENDING','PENDING',true,'No live approved binding exists in TEST; no synthetic execution performed.');